create table if not exists public.dreem_gate_offline_incidents(id uuid primary key default gen_random_uuid(),school_id uuid not null,actor_id uuid not null,credential_digest text not null,collector_digest text,decision text not null check(decision='denied'),reason text not null,captured_at timestamptz not null,device_id text not null,idempotency_key text not null,synced_at timestamptz not null default now(),unique(school_id,idempotency_key));
create index if not exists dreem_gate_offline_incidents_school_idx on public.dreem_gate_offline_incidents(school_id,captured_at desc);alter table public.dreem_gate_offline_incidents enable row level security;revoke all on public.dreem_gate_offline_incidents from anon;grant select on public.dreem_gate_offline_incidents to authenticated;drop policy if exists "gate authorized reads offline incidents" on public.dreem_gate_offline_incidents;create policy "gate authorized reads offline incidents" on public.dreem_gate_offline_incidents for select to authenticated using(private.dreem_has_role(school_id,array['leadership','support','security_guard']));
create or replace function public.dreem_ingest_gate_offline_denial(p_school_id uuid,p_credential_digest text,p_collector_digest text,p_reason text,p_captured_at timestamptz,p_device_id text,p_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid;begin if not private.dreem_has_role(p_school_id,array['leadership','support','security_guard'])then raise exception 'Gate role required';end if;if length(trim(p_credential_digest))<16 then raise exception 'Credential digest required';end if;if length(trim(p_reason))<3 then raise exception 'Denial reason required';end if;insert into public.dreem_gate_offline_incidents(school_id,actor_id,credential_digest,collector_digest,decision,reason,captured_at,device_id,idempotency_key)values(p_school_id,(select auth.uid()),trim(p_credential_digest),nullif(trim(coalesce(p_collector_digest,'')),''),'denied',trim(p_reason),p_captured_at,trim(p_device_id),p_idempotency_key)on conflict(school_id,idempotency_key)do update set idempotency_key=excluded.idempotency_key returning id into v_id;insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(p_school_id,(select auth.uid()),'gate.offline_denial_synced','gate_offline_incident',v_id,jsonb_build_object('captured_at',p_captured_at,'device_id',p_device_id));return v_id;end;$$;
revoke all on function public.dreem_ingest_gate_offline_denial(uuid,text,text,text,timestamptz,text,text) from public;grant execute on function public.dreem_ingest_gate_offline_denial(uuid,text,text,text,timestamptz,text,text) to authenticated;